def create_and_call_object(
    cls: Type,
    call_args: tuple = (),
    call_kwargs: dict = None,
    init_args: tuple = (),
    init_kwargs: dict = None,
) -> Any:
    if call_kwargs is None:
        call_kwargs = {}
    if init_kwargs is None:
        init_kwargs = {}
    return cls(*init_args, **init_kwargs)(*call_args, **call_kwargs)

