@abc.abstractmethod
@check_shapes(
    "return: []",
)
def maximum_log_likelihood_objective(self, *args: Any, **kwargs: Any) -> tf.Tensor:
    """
    Objective for maximum likelihood estimation. Should be maximized. E.g.
    log-marginal likelihood (hyperparameter likelihood) for GPR, or lower
    bound to the log-marginal likelihood (ELBO) for sparse and variational
    GPs.
    """
    raise NotImplementedError

def _training_loss(self, *args: Any, **kwargs: Any) -> tf.Tensor:
    """
    Training loss definition. To allow MAP (maximum a-posteriori) estimation,
    adds the log density of all priors to maximum_log_likelihood_objective().
    """
    return -(self.maximum_log_likelihood_objective(*args, **kwargs) + self.log_prior_density())

def reshape_range(tensor, i, j, shape):
    """Reshapes a tensor between dimensions i and j."""
    t_shape = shape_list(tensor)
    target_shape = t_shape[:i] + shape + t_shape[j:]
    return tf.reshape(tensor, target_shape)

def split_last_dimension(x, n):
    x_shape = shape_list(x)
    m = x_shape[-1]
    if isinstance(m, int) and isinstance(n, int):
        assert m % n == 0
    return tf.reshape(x, x_shape[:-1] + [n, m // n])

def _get_file_list(dataset_path, dirs, ext):
    files = []
    for _dir in dirs:
        files += glob.glob(os.path.join(dataset_path, _dir, f"*{ext}"))
    return files

@classmethod
def _get_data_pair(cls, wavs, labels):
    label_path_mapping = {os.path.basename(label): label for label in labels}
    pair = []
    for wav in wavs:
        basename = os.path.basename(wav)
        label_name = cls._name_transform(basename).replace(".wav", cls.label_ext)
        label_path = label_path_mapping[label_name]
        assert os.path.exists(label_path)
        pair.append((wav, label_path))
    return pair

