def _reduce_func(count, element):
    element = tf.nest.flatten(element)[0]
    batch_size = tf.shape(element)[0]
    return count + tf.cast(batch_size, count.dtype)

return dataset.reduce(tf.constant(0, dtype=tf.int64), _reduce_func)

