def sample_uniform(in_shape, bounds):
    n_samples = np.prod(in_shape[:-1])
    samples = np.zeros(in_shape)
    for i, b in enumerate(bounds):
        samples[..., i] = np.random.uniform(low=b[0], high=b[1], size=n_samples)

