def make_perturb_func(
    perturb_func: PerturbFunc, perturb_func_kwargs: Mapping[str, ...] | None, **kwargs
) -> PerturbFunc | functools.partial:
    if perturb_func_kwargs is not None:
        func_kwargs = kwargs.copy()
