    elif len(batch_shape) == 2:
        return batch_shape
    elif len(batch_shape) == 1:
        return batch_shape + [1]

def smooth_by_neighbours(labels, kernel, n_classes):
    kernel = np.array(kernel).reshape(-1, 1)
    one_hot_labels = to_categorical(labels, n_classes)
    return convolve2d(one_hot_labels,
                      kernel,
                      mode="same", boundary='symm')

def smoothen(one_hot_labels, max_alpha, n_classes):
    alpha = np.random.rand() * max_alpha
    return (1-alpha) * one_hot_labels + (alpha/n_classes)

def concatenate_true_pred_pairs(pairs=None, trues=None, pred=None):
    if pairs is None and (trues is None or pred is None):
        raise ValueError("Must specify either 'pairs' argument "
                         "or both 'trues' and 'pred' arguments")
    if pairs is not None:
        trues, pred = zip(*pairs)
    return np.concatenate(list(trues)), np.concatenate(list(pred))

