@staticmethod
def loss_fn(y, yp):
    diff = y - yp.view(y.shape)
    return torch.sum(diff.view(-1) ** 2).detach().cpu().data.numpy()

@staticmethod
def loss_fn(y, yp):
    yp = yp.reshape(*y.shape)
    valid_idx = torch.bitwise_not(torch.isnan(y))
    y = y[valid_idx]
    yp = yp[valid_idx]

    y = y.to(torch.float)
    diff = y - yp.view(y.shape)

    return torch.sum(torch.abs(diff).view(-1)).detach().cpu().data.numpy()

