def select(self, m_pack: MultiPack) -> Iterator[DataPack]:
        reverse = self.configs.reverse_selection

        for name, pack in m_pack.iter_packs():
            if reverse:
                if not self.will_select(name, pack, m_pack):
                    yield pack
            else:
                if self.will_select(name, pack, m_pack):
                    yield pack

