@staticmethod
def objective(input_data):
    x, y = input_data[..., -2], input_data[..., -1]
    z = tf.cos(2.0 * x) * tf.cos(y) + tf.sin(x)
    return z[:, None]

@staticmethod
def constraint(input_data):
    x, y = input_data[:, -2], input_data[:, -1]
    z = tf.cos(x) * tf.cos(y) - tf.sin(x) * tf.sin(y)
    return z[:, None]

