def map_features(x1, x2, degree=1):
    X = np.ones((x1.shape[0], 1))
    for i in range(1, degree + 1):
        for j in range(0, i + 1):
            f = (x1 ** (i - j)) * (x2 ** j)
            X = np.hstack((X, f.reshape(-1, 1)))

