def ensure_sparse(loss_and_metric_names):
    """
    Checks that 'sparse' is a substring of each string in a list of loss and/or
    metric names. Raises NotSparseError if one or more does not contain the
    substring.
    """
    for i, m in enumerate(loss_and_metric_names):
        if "sparse" not in m:
            raise SPARSE_ERR

def _init(string_list, tf_funcs, custom_funcs, logger=None, **kwargs):
    initialized = []
    tf_funcs = ensure_list_or_tuple(tf_funcs)
    for func_or_class in ensure_list_or_tuple(string_list):
        modules_found = list(filter(None, [getattr(m, func_or_class, None)
                                           for m in tf_funcs]))
        if modules_found:
            initialized.append(modules_found[0])  # return the first found
        else:
            # Fall back to look in custom module
            initialized.append(getattr(custom_funcs, func_or_class))

@wraps(function)
def wrapper(*args, **kwargs):
    for i, (o, t) in enumerate(zip(args, _types)):
        valid = False
        if isinstance(t, (tuple, list)):
            for tt in t:
                if isinstance(o, tt):
                    valid = True
        else:
            if isinstance(o, t):
                valid = True
        if not valid:
            raise ValueError("Invalid input passed to '%s'. "
                             "Expected type(s) %s (got %s)" % (function.__name__,
                                                               t,
                                                               type(o).__name__))
    return function(*args, **kwargs)

def one_hot_encode_y(y, n_classes=135):
    y = np.asarray(y)
    if n_classes == 1:
        return reshape_add_axis(y, len(y.shape)-1)
    else:
        from keras.utils import to_categorical
        shape = y.shape
        y = to_categorical(y, num_classes=n_classes).astype(np.uint8)
        y = y.reshape(shape + (n_classes,))
    return y

def apply_scaling(X, scaler, ignore_less_eq=None):
    # Get scaler
    multi_scaler = get_scaler(scaler, ignore_less_eq=ignore_less_eq)

    # Fit and apply transformation
    return multi_scaler.fit_transform(X)

def fit(self, X, *args, **kwargs):
    if X.ndim != 4:
        raise ValueError("Invalid shape for X (%s)" % X.shape)

    # Set number of channels
    self.n_channels = X.shape[-1]

for i in range(self.n_channels):
    sc = self.scaler_class(*self.scaler_args, **self.scaler_kwargs)
    xs = X[..., i]
    if self.ignore_less_eq is not None:
        xs = xs[np.where(xs > self.ignore_less_eq[i])]
    sc.fit(xs.reshape(-1, 1), *args, **kwargs)

def get_scaler(scaler, *args, ignore_less_eq=None, **kwargs):
    scaler = preprocessing.__dict__[scaler]
    return MultiChannelScaler(scaler=scaler,
                              ignore_less_eq=ignore_less_eq,
                              *args, **kwargs)

def expand_to_dim(values, dim):
    expanded = []
    for v in values:
        if not isinstance(v, (tuple, list, np.ndarray)):
            v = [v]
        if isinstance(v, np.ndarray):
            v = list(v)
        if len(v) != dim:
            v *= dim
        expanded.append(np.array(v))

