def is_elf64(root: str, path: str) -> bool:
    file_path = os.path.join(root, path)
    try:
        with open(file_path, "rb") as f:
            header = f.read(5)
            # '\x7fELF' means it's an ELF file, '\x02' means 64-bit
            return header == b"\x7fELF\x02"
    except IOError:
        return False

return (
