def call_vtk(obj, method, args=None):
    if args is None:
        try:
            return getattr(obj, method)()
        except:
            return getattr(obj, method)(None)

    if isinstance(args, dict):
        return getattr(obj, method)(**args)

    return getattr(obj, method)(args)

