def to_complex(x, n):
    return tf.complex(
        tf.cast(x[..., :n], dtype=tf.float32),
        tf.cast(x[..., n:], dtype=tf.float32),
    )

def to_real(x):
    return tf.concat([
        tf.math.real(x),
        tf.math.imag(x),
    ], axis=-1)

