def set_group_permissions(path, system='AD', owner='GSK'):
    """Sets file and group permissions..."""
    if system != 'LC':
        system = 'AD'
    owner_group_map = dict(GSK = {'LC' : 'gskcraa', 'AD' : 'gskusers-ad'},
                           public = {'LC' : 'atom', 'AD' : 'atom'} )
    group = owner_group_map[owner][system]
    shutil.chown(path, group=group)
    os.chmod(path, 0o770)

def rms_error(y_real, y_pred):
    return np.sqrt(mean_squared_error(y_real, y_pred))

def negative_predictive_value(y_real, y_pred):
    TN = sum((y_pred == 0) & (y_real == 0))
    FN = sum((y_pred == 0) & (y_real == 1))

def negative_predictive_value(y_real, y_pred):
    TN = sum((y_pred == 0) & (y_real == 0))
    FN = sum((y_pred == 0) & (y_real == 1))
    if TN + FN == 0:
        return 0.0
    else:
        return float(TN)/float(TN+FN)

