def __call__(self, images: np.ndarray) -> np.ndarray:
    shape = images.shape
    if len(shape) == 4:
        # F x H x W x C -> C x F x H x W
        return images.transpose(3, 0, 1, 2)
    elif len(shape) == 3:
        # H x W x C -> C x H x W
        return images.transpose(2, 0, 1)

